from collections import deque


def minutes_to_cover(grid):
    rows, cols = len(grid), len(grid[0])
    dist = [[-1] * cols for _ in range(rows)]
    queue = deque()
    open_cells = 0
    for r in range(rows):
        for c in range(cols):
            if grid[r][c] == 'S':
                dist[r][c] = 0
                queue.append((r, c))
            elif grid[r][c] == '.':
                open_cells += 1
    minutes = 0
    while queue:
        r, c = queue.popleft()
        for nr, nc in ((r + 1, c), (r - 1, c), (r, c + 1), (r, c - 1)):
            if 0 <= nr < rows and 0 <= nc < cols and grid[nr][nc] == '.' and dist[nr][nc] == -1:
                dist[nr][nc] = dist[r][c] + 1
                minutes = dist[nr][nc]
                open_cells -= 1
                queue.append((nr, nc))
    return minutes if open_cells == 0 else -1
